/**
 * Shape of the solver preflop chart data, generated by scripts/make-preflop.mjs: src/data/sets/preflopIndex.ts (every
 * shipped stage's PreflopStageMeta, loaded with the app) and src/data/sets/preflopStages/<stage id>.ts (one PreflopStage
 * per file, its default export, loaded on first use). Hand-written so the generator, the chart set (preflop.ts) and the
 * tests share one contract; the generated files only hold data. Design: docs/preflop-solver.md (§6.2).
 */

export type PreflopKind = "rfi" | "vsOpen" | "vs3bet" | "vs4bet" | "squeeze" | "vsLimp" | "vsShove";

export interface PreflopAction {
  /** Unique within the scenario; never "fold" (fold is the remainder). */
  key: string;
  /** Korean button label, e.g. "오픈 2.2bb", "3벳 6.6bb", "올인". */
  label: string;
  color: "open" | "raise" | "allin" | "call";
  /** The hero's total bet after the action in bb (ante excluded): on every raise and jam, never on a call, limp or
   *  check. A jam's is the hero's stack (less the ante for the BB), capped by the largest stack still in. */
  to?: number;
  /**
   * Range string (src/poker/range.ts syntax). Frequencies are snapped to multiples of 0.1 per hand and, together
   * with the earlier actions of the scenario, sum to at most 1, so buildScenario's "earlier action takes first"
   * fill reproduces them exactly.
   */
  range: string;
}

/** Composition checks that flag cells as a known model or tree artifact (docs §5.2, §6.10, §8). */
export type PreflopFlagCode = "PF-SANITY-9" | "PF-SANITY-11" | "PF-SANITY-12" | "PF-SANITY-13" | "PF-SANITY-14";

export interface PreflopFlag {
  code: PreflopFlagCode;
  /** Range string, every value 1, never empty: in-reach hands whose cell shows the artifact as a clear model
   *  preference (the chart shows the cell pure and it carries no close mark). */
  hands: string;
  /** Range string, every value 1: the hands `hands` are measured against (any cell). Omitted for PF-SANITY-12. */
  vs?: string;
}

export interface PreflopScenario {
  /** Unique within the stage, e.g. "rfi-btn", "bb-vs-btn-open", "bb-at-co-open-btn-call". */
  id: string;
  kind: PreflopKind;
  hero: string;
  villain?: string;
  villainSeats?: string[];
  chip: string;
  title: string;
  /** Sizes, notes and the confidence line, in Korean. */
  description: string;
  /** Public line, e.g. "CO 2.2 · BTN 콜". */
  line: string;
  /**
   * The hero's earlier decisions on this line as "scenarioId:actionKey", in order; omitted when the hero acts for
   * the first time. The hero's reach is the product of those actions' frequencies.
   */
  reachFrom?: string[];
  /** % of the 1,326 combos the hero still holds here (combo-weighted reach). */
  reachPct: number;
  /** The hero cannot fold here (the BB facing an SB limp). */
  noFold?: true;
  /** % of dealt hands in which this decision comes up. */
  occ: number;
  /** Reach-weighted local regret at this node, bb. */
  regret: number;
  confidence: "high" | "mid" | "low";
  /** pp the chart moved in the sensitivity solves (largest reach-weighted total variation). */
  move: number;
  /**
   * Close calls (§6.9): 169 characters in ALL_HANDS order (the grid row by row from AA). "." = no mark; otherwise a
   * lowercase hex digit, the bitmask over the legend actions (`actions` in order, then fold unless noFold; bit i =
   * legend action i) whose best-response value against σ̄ is within the stage's closeEps of the best eligible one.
   * Only where the chart shows the cell pure; the chart's action is in the set, at least two bits are set, and no bit
   * names a non-fold action that takes under 1% of the reaching range. Omitted when no hand is marked.
   */
  close?: string;
  /**
   * Model-sensitive cells (§6.6): 169 characters in ALL_HANDS order, "." or a lowercase hex bitmask over the legend
   * actions as in `close`. A cell is marked where the chart shows it pure but in at least one sensitivity solve its
   * action falls below 0.5; the mask is the set of actions on top (the largest share) in the main solve or in any
   * sensitivity solve, the chart's action among them, at least two bits. Only in a stage that ran its sensitivity
   * solves; omitted when no hand is marked.
   */
  sens?: string;
  /** Known-artifact flags (§6.10), in the order 9, 11, 12, 13, 14. Omitted when none. */
  flags?: PreflopFlag[];
  /** Non-fold actions in display order. */
  actions: PreflopAction[];
}

export interface PreflopStage {
  /** e.g. "100bb-2.2", "100bb-3", "55bb-2.2", "35bb-2", "10bb-pf". */
  id: string;
  /** Korean, e.g. "100bb · 오픈 2.2bb". */
  label: string;
  /** Korean stage description: stacks, sizes, "서로 최선인 균형 근사(착취 아님)". */
  description: string;
  /** Everyone's starting stack in bb (the BB pays the 1bb ante out of it). */
  stack: number;
  /** First-in open size in bb (UTG–BTN). */
  open: number;
  sizes: {
    sbRaise: number;
    iso: number;
    ip3: number;
    blind3: number;
    bbVsSb3: number;
    sqzPerCallerIP: number;
    sqzPerCallerBlind: number;
    fourIP: number;
    fourOOP: number;
    limpReraise: number;
    jamMax: number;
  };
  /** cold4 "none" after the fallback re-solve without cold jams behind a 3-bet, or by the stage's preset (25bb).
   *  mode "pushfold" for a push/fold stage (first in: fold or jam; facing a jam: fold or call); omitted for the full
   *  tree. */
  tree: { cold4: "none" | "jam"; allinOrder: "priority"; mode?: "pushfold" };
  iterations: number;
  /** % of dealt hands; non-rfi scenarios below their kind's threshold are not exported. */
  occThreshold: number;
  /** Thresholds actually used per kind after the size ladder, % of dealt hands. vs3bet is the non-cold spots'. */
  occThresholdByKind: Record<PreflopKind, number>;
  /** % of dealt hands: the cold vs3bet spots' own threshold (their size-ladder group's, at least vs3bet's). Cold
   *  spots below it are not exported. Optional: data written before the field existed has none. */
  occThresholdCold?: number;
  /** Per seat (UTG..BB), each in that seat's own world, mbb/hand. */
  brGainMbb: number[];
  nashConvMbb: number;
  /** Snapped (exported) profile: largest per-seat best-response gain, mbb/hand. */
  snappedGainMbb: number;
  /** Per seat, bb/hand, own-world EV under the mass method of card removal; the sum is NOT 0. */
  ev: number[];
  diag: { evSum: number; frozenOccPct: number; negativeShares: number };
  /** The flop valuation: model B with its fit, or showdown equity alone for a stage that never sees a flop
   *  (push/fold: no realization model, no fit). */
  model:
    | {
        id: "modelB-rank9";
        fitHash: string;
        sprAlpha: number;
        sprSurplus: number;
        packs: Record<string, { version: number; flops: number }>;
      }
    | { id: "showdown-equity" };
  /** sha256 of the equity table (scripts/equity-cache.mjs equityTableSha256). */
  equityTable: string;
  /** bb per arrival: the threshold of the scenarios' `close` strings. Omitted in data written before it. */
  closeEps?: number;
  /** % of dealt hands; set only when PF-SIZE-1 made the generator drop close strings: spots below it carry none. */
  closeMinOcc?: number;
  scenarios: PreflopScenario[];
}

/** A stage without its scenarios: what src/data/sets/preflopIndex.ts holds for every shipped stage. */
export type PreflopStageMeta = Omit<PreflopStage, "scenarios">;
